function supportingOwnerValidation(script: string): { script: string; status: "PASS"; safeDigest: string; rawOutput: string } {
  const child = spawnSync("npm", ["run", script], { cwd: repositoryRoot, encoding: "utf8", env: { ...process.env, NODE_ENV: "test", NODE_OPTIONS: "--conditions=react-server" }, timeout: 120_000, maxBuffer: 32 * 1024 * 1024 });
  assert.equal(child.status, 0, `${script} failed`); const output = `${child.stdout}\n${child.stderr}`;
  assert.match(output, /PASS|"result"\s*:\s*"PASS"/);
  return { script, status: "PASS", safeDigest: safeDigestOfText(script, output), rawOutput: output };
}

function safeDigestOfText(label: string, output: string): string {
  const safeCategories = output.split("\n").filter(line => /PASS|result/.test(line)).map(line => line.replace(/\d{4}-\d\d-\d\dT[^" ]+/g, "<time>").replace(/\d+/g, "#"));
  return safeDigest({ label, safeCategories });
}

async function implementationDigest(): Promise<string> {
  const files = ["nonDisclosureContracts.ts", "nonDisclosureThreatCorpus.ts", "nonDisclosureDerivedInfluenceOracle.ts", "protectedValueScanner.ts", "runNonDisclosureThreatHarness.ts"].map(name => path.join(repositoryRoot, "scripts/alpha-readiness", name));
  return safeDigest(await Promise.all([...files, path.join(repositoryRoot, "package.json")].map(async file => safeDigest(await readFile(file, "utf8")))));
}

function renderReport(result: Record<string, unknown>): string {
  const totals = result.caseTotals as { total: number; passed: number; failed: number }, positive = result.positiveControls as { total: number; passed: number };
  const fresh = result.freshProcess as { total: number }, successor = result.successor as { exactReplay: boolean }, cleanup = result.cleanup as { status: string }, scanner = result.scanner as { leakageFindings: number };
  return `# AR-1A Non-Disclosure Foundation Report\n\n- Foundation: **${result.foundationStatus}**\n- Product readiness: **${result.productReadinessStatus}**\n- Blocker: \`EMPTY_CONTRIBUTION_CLOSURE\`\n- Threat cases: ${totals.passed}/${totals.total} passed\n- Positive controls: ${positive.passed}/${positive.total} passed\n- Fresh-process cases: ${fresh.total}\n- Successor exact replay: ${successor.exactReplay ? "PASS" : "FAIL"}\n- Scanner leakage findings: ${scanner.leakageFindings}\n- Cleanup: **${cleanup.status}**\n- Evidence hygiene: **${result.evidenceHygieneStatus}**\n- Source digest: \`${result.sourceDigest}\`\n- Result digest: \`${result.resultDigest}\`\n\nThe foundation uses isolated owner-issued Product state and measured protected-body reads. Product readiness remains blocked because the existing owner rejects Capture and closure for an exact empty contribution set without creating a synthetic contribution or invalid closure.\n`;
}

class MeasuredBodies implements ProductArtifactBodyRepository {
  readonly backend = "filesystem" as const;
  reads = 0; stages = 0;
  constructor(private readonly delegate: ProductArtifactBodyRepository) {}
  async stage(input: ProductArtifactBodyStageRequestV1) { this.stages += 1; return this.delegate.stage(input); }
  async readStagedExact(ref: ProductArtifactBodyRefV1) { this.reads += 1; return this.delegate.readStagedExact(ref); }
}

type World = Awaited<ReturnType<typeof createWorld>>;
async function createWorld(label: string, selectedContent: readonly string[], allocatedRoots: string[]) {
  const root = await mkdtemp(path.join(tmpdir(), `discovery-leadership-conversation-replay-ar1a-${label}-`));
  allocatedRoots.push(root);
  const lineageFixtureRoot = await mkdtemp(path.join(tmpdir(), `discovery-northstar-preparation-lineage-ar1a-${label}-`));
  allocatedRoots.push(lineageFixtureRoot);
  const locations = { runtimeRoot: path.join(root, "runtime"), workflowRoot: path.join(root, "workflow"), sourceContentRoot: path.join(root, "content"), lineageFixtureRoot };
  const setup = await provisionNorthstarPreparationLineageFixture({ environment: "test", fixtureRoot: locations.lineageFixtureRoot });
  const fixture = northstarLeadershipConversationFixture(setup.seed.productQuestionId);
  const scope = { organizationId: fixture.organizationId, type: "organization" as const, id: fixture.organizationId };
  const topology = createCanonicalScopeTopology({ organizationId: fixture.organizationId, topologyVersion: 1, effectiveAt: fixture.at, nodes: [scope], relationships: [] });
  let runtime = createEmptyOrganizationRuntime({ organizationId: fixture.organizationId, name: "AR1A synthetic organization", now: fixture.at });
  runtime.memory.canonicalScopeLineageIndex = createCanonicalScopeLineageIndex({ organizationId: fixture.organizationId, topology });
  runtime = createDurableProductQuestion({ runtime, title: "What constrains delivery?", questionId: fixture.questionId, createdAt: fixture.at }).runtime;
  await new FilesystemOrganizationRuntimeRepository(locations.runtimeRoot).create(fixture.organizationId, new TextEncoder().encode(JSON.stringify(runtime)), { requestId: `ar1a-${label}-runtime`, operatorId: fixture.actorId });
  const bodies = new MeasuredBodies(createProductArtifactBodyRepository({ root: path.join(root, "bodies") }));
  let artifactHookReads = 0, sourceHookReads = 0;
  const composition = createLeadershipConversationServerCompositionForValidation({ ...locations, userId: fixture.actorId, organizationId: fixture.organizationId, bodyRepository: bodies, onProtectedArtifactRead: () => { artifactHookReads += 1; }, onProtectedSourceContentRead: () => { sourceHookReads += 1; } });
  const identity = { userId: fixture.actorId, organizationId: fixture.organizationId, questionId: fixture.questionId, conversationId: fixture.conversationId };
  let ownerInvocations = 0;
  await composition.recordContext({ ...identity, idempotencyKey: "context", title: "Weekly review", purpose: "Resolve a constraint", intendedOutcome: "Choose one action", timeframe: "Weekly", participants: [], leaderContext: null }); ownerInvocations += 1;
  const repository = createProductWorkflowArtifactRepository({ root: locations.workflowRoot, environment: "test" });
  let stored = await repository.read(fixture.organizationId);
  await composition.recordPreparation({ ...identity, idempotencyKey: "prepare", contextVersionId: stored.store.contexts[0]!.contextVersionId, content: NORTHSTAR_PREPARED_CONTENT, lineage: NORTHSTAR_PREPARED_LINEAGE, changeSummary: null }); ownerInvocations += 1;
  stored = await repository.read(fixture.organizationId);
  await composition.freeze({ ...identity, idempotencyKey: "freeze", artifactVersionId: stored.store.preparedWorkPublications![0]!.artifactRevision, privateWorkingContribution: { seriesId: `leadership-conversation-series:${fixture.conversationId}`, occurrenceId: fixture.conversationId, authorizationRevision: NORTHSTAR_PREPARED_LINEAGE.authorizedProjectionRevision, provenanceDigest: NORTHSTAR_PREPARED_LINEAGE.authorizedProjectionDigest, selectedContent } }); ownerInvocations += 1;
  stored = await repository.read(fixture.organizationId);
  return { root, lineageFixtureRoot, locations, fixture, identity, composition, repository, bodies, ownerInvocations, artifactHookReads: () => artifactHookReads, sourceHookReads: () => sourceHookReads, snapshot: stored.store.frozenSnapshotPublications![0]! };
}

