  const governanceContext = { organizationId: world.fixture.organizationId, operationBatch, scopeLineageIndex, envelope: createCanonicalEvidenceContributionLineageEnvelope({ context: operationContext, admissionBatch: operationBatch }) };
  const signals = {
    beliefs: [{ id: "belief:ar1a-operation-linked", statement: "Reviewed evidence supports a bounded operational constraint.", confidence: 0.7, supportingMechanismIds: ["mechanism:ar1a-operation-linked"] }],
    mechanisms: [{ id: "mechanism:ar1a-operation-linked", statement: "Reviewed evidence supports a bounded operational constraint.", confidence: 0.7, supportingEvidenceIds: evidenceIds, supportingExplanationSeedIds: ["seed:ar1a-operation-linked"], supportingReasoningPathIds: ["path:ar1a-operation-linked"], scopeRef: rootScope, outcomeRefs: [{ type: "indirectEffect" as const, id: "outcome:ar1a-operation-linked" }] }],
    concepts: [{ id: "concept:ar1a-operation-linked", summary: "bounded operational constraint" }], evidence: evidenceIds.map(id => ({ id })),
  };
  const theoryState = consolidateOrganizationalTheories({ existingTheories: [], ...signals, canonicalGovernanceContext: governanceContext, contradictoryEvidenceIds: [], now: world.fixture.at });
  const completion = completeOrganizationalExplanations({ organizationId: world.fixture.organizationId, seeds: [{ id: "seed:ar1a-operation-linked", organizationId: world.fixture.organizationId, semanticKey: "seed:ar1a-operation-linked", title: "Bounded operational constraint", summary: "Reviewed evidence supports a bounded operational constraint.", explanationType: "coordination", scope: rootScope, outcomeRefs: [{ type: "indirectEffect", id: "outcome:ar1a-operation-linked" }], reasoningPathIds: ["path:ar1a-operation-linked"], reasoningRelationshipIds: [], evidenceIds, supportedPathIds: [], explainedEffectIds: [], relatedRootCauseIds: [], relatedLeveragePointIds: [], relatedExecutiveConclusionIds: [], assumptions: [], evidenceReferences: [], confidence: 0.7, generatedAt: world.fixture.at }], mechanisms: [{ id: "mechanism:ar1a-operation-linked", statement: "Reviewed evidence supports a bounded operational constraint.", mechanismType: "coordination", category: "coordination", description: "Bounded owner-issued explanation fixture.", confidence: 0.7, strength: 0.7, supportingEvidenceIds: evidenceIds, supportingObservationIds: [], supportingPhenomenonIds: [], supportingExplanationIds: ["seed:ar1a-operation-linked"], supportingExplanationSeedIds: ["seed:ar1a-operation-linked"], supportingReasoningPathIds: ["path:ar1a-operation-linked"], reasoningPathIds: ["path:ar1a-operation-linked"], scopeRef: rootScope, outcomeRefs: [{ type: "indirectEffect", id: "outcome:ar1a-operation-linked" }], affectedEntityIds: [], affectedProcessIds: [], conditions: [], implications: [], firstObserved: world.fixture.at, lastObserved: world.fixture.at } as never], beliefs: signals.beliefs as never, theories: theoryState.theories, contradictionIds: [], evidenceContext: { organizationId: world.fixture.organizationId, evidence: evidenceIds.map(id => ({ id })), relationships: [] }, canonicalGovernanceContext: governanceContext, now: world.fixture.at });
  assert.equal(completion.failures.length, 0); assert.equal(completion.explanations.length, 1);
  const explanationLineage = completion.explanations[0]!.canonicalGovernanceLineage; assert.ok(explanationLineage);
  const operationRef = explanationLineage.operationRefs[0]!;
  assert.equal(operationRef.contributionOperationId, operation.contributionOperationId);
  assert.equal(operationRef.questionId, world.fixture.questionId);
  assert.equal(operationRef.purposeRef, world.fixture.purposeRef);
  assert.deepEqual([...new Set(explanationLineage.directMaterialSupports.map(value => value.canonicalEvidenceId))].sort(), [...new Set(operationBatch.admissions.map(value => value.canonicalEvidenceId))].sort());
  const runtime = structuredClone(stored.runtime); runtime.memory.organizationalExplanations = completion.explanations;
  const persisted = await repository.replace(world.fixture.organizationId, new TextEncoder().encode(JSON.stringify(runtime)), stored.revision, { requestId: "ar1a-persist-owner-issued-explanation", operatorId: world.fixture.actorId });
  assert.equal(persisted.runtime.memory.organizationalExplanations.length, 1);
